DROP POLICY inspiration_update ON public.cultural_inspirations;
CREATE POLICY inspiration_update ON public.cultural_inspirations FOR UPDATE TO authenticated USING (hidden_at IS NULL AND trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()) AND (creator_id=auth.uid() OR (mode='team' AND partner_id=auth.uid()))) WITH CHECK (hidden_at IS NULL AND trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()) AND (creator_id=auth.uid() OR (mode='team' AND partner_id=auth.uid())));
CREATE OR REPLACE FUNCTION trip_private.reveal_inspiration_votes(p_card uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.cultural_inspirations SET votes_revealed_at=now() WHERE id=p_card AND creator_id=auth.uid() AND mode='challenge' AND hidden_at IS NULL AND reveal_on<=CURRENT_DATE AND votes_revealed_at IS NULL AND trip_private.feature_on(trip_id,'inspiration') AND trip_private.is_trip_member(trip_id,auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Only the approved creator can reveal votes on a displayed challenge'; END IF; END $$;
CREATE OR REPLACE FUNCTION trip_private.hide_inspiration(p_card uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; UPDATE public.cultural_inspirations SET hidden_at=now() WHERE id=p_card AND hidden_at IS NULL; IF FOUND THEN INSERT INTO trip_private.inspiration_moderation(card_id,actor,action) VALUES(p_card,auth.uid(),'hide'); END IF; END $$;